def main() -> None:
    if DB_PATH.exists():
        print(f"Using existing database at {DB_PATH}")
    db = Database(DB_PATH)
    field_service = FieldService(db)
    entity_service = EntityService(db)

    existing_keys = {f["key"] for f in field_service.list_fields(limit=1000)}
    new_specs = [spec for spec in FIELD_SPECS if spec["key"] not in existing_keys]
    created = field_service.bulk_create_fields(new_specs) if new_specs else 0
    print(f"Fields registered this run: {created} (schema had {len(existing_keys)} already)")

    inserted = 0
    updated = 0
    for symbol in SYMBOLS:
        entity_id = symbol["key"]
        try:
            entity_service.get_entity(entity_id, include_cells=False)
            updated += 1
        except KeyError:
            entity_service.create_entity(
                label=symbol["latex"],
                kind="math_symbol",
                entity_id=entity_id,
            )
            inserted += 1
        series = symbol.get("series", "NS")
        for field_key in (
            "latex",
            "series",
            "first_appearance",
            "label_zh",
            "label_en",
            "definition_zh",
            "definition_en",
            "defining_relation",
            "notes",
        ):
            if field_key == "series":
                value = series
            else:
                value = symbol.get(field_key)
            if value is None:
                continue
            entity_service.set_cell(entity_id, field_key, value, source="amral-ns-ingest-2026-08-24")

    print(f"Entities: {inserted} created, {updated} already present (cells refreshed either way)")
    print(f"Total symbol records in this pass: {len(SYMBOLS)}")
    print(f"Database file: {DB_PATH}")


if __name__ == "__main__":
    main()
